#!/usr/bin/env node
// Copies the flag-icons 4x3 SVG set into public/flags so the nav menu can serve
// a flag for any country the CMS grows into, without a runtime API call and
// without committing ~250 vendored SVGs to the repo.
//
// flag-icons (lipis) draws each flag at full detail, coats of arms included.
// It replaced country-flag-icons, whose simplified emblems (Mexico, Peru) read
// as smudges. Every file is the same 4:3 canvas, so the flags line up at one
// size; CountryFlag crops them to its 3:2 frame with object-cover.
//
// public/flags is gitignored and regenerated by `pnpm dev` and `pnpm build`.

import { createRequire } from 'node:module'
import { copyFile, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const require = createRequire(import.meta.url)
const clientRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const destination = path.join(clientRoot, 'public', 'flags')
const stampFile = path.join(destination, '.source')

const packageJsonPath = require.resolve('flag-icons/package.json')
const { name, version } = JSON.parse(await readFile(packageJsonPath, 'utf8'))
const stamp = `${name}@${version}`
const source = path.join(path.dirname(packageJsonPath), 'flags', '4x3')

// Only ISO 3166-1 alpha-2 codes: CountryFlag accepts nothing else, and the set
// also ships subdivisions (gb-eng, es-ct) and groupings (arab, eu).
const sourceFiles = (await readdir(source)).filter((file) => /^[a-z]{2}\.svg$/.test(file))
if (sourceFiles.length === 0) {
  throw new Error(`No flag SVGs found in ${source}`)
}

// Already in sync: a no-op keeps `pnpm dev` startup cheap.
const existingStamp = await readFile(stampFile, 'utf8').catch(() => null)
if (existingStamp === stamp) {
  process.exit(0)
}

await rm(destination, { recursive: true, force: true })
await mkdir(destination, { recursive: true })
await Promise.all(
  sourceFiles.map((file) =>
    copyFile(path.join(source, file), path.join(destination, file.toUpperCase().replace('.SVG', '.svg'))),
  ),
)
await writeFile(stampFile, stamp)

console.log(`[flags] synced ${sourceFiles.length} flags from ${stamp} -> public/flags`)
